class Solution { public TreeNode createBinaryTree(int[][] descriptions){Map<Integer,TreeNode> nodes=new HashMap<>();Set<Integer> children=new HashSet<>();for(int[] description:descriptions){TreeNode parent=nodes.computeIfAbsent(description[0],TreeNode::new);TreeNode child=nodes.computeIfAbsent(description[1],TreeNode::new);if(description[2]==1)parent.left=child;else parent.right=child;children.add(description[1]);}for(Map.Entry<Integer,TreeNode> entry:nodes.entrySet())if(!children.contains(entry.getKey()))return entry.getValue();return null;} }
